"use client";

import { useEffect, useMemo, useState, useCallback } from "react";
import axios from "axios";
import type { CategoryNode } from "../types";
import { buildCategoryColumns } from "../utils/buildCategoryColumns";

export type UseCategoryTreeResult = {
  categories: CategoryNode[];
  loadingCategories: boolean;
  categoryError: string | null;
  isCategoryOpen: boolean;
  categoryPath: CategoryNode[];
  selectedLeaf: CategoryNode | null;
  categoryColumns: CategoryNode[][];
  selectedPathLabel: string;
  handleCategoryClick: (levelIndex: number, node: CategoryNode) => void;
  openCategoryPopup: () => void;
  closeCategoryPopup: () => void;
};

export function useCategoryTree(): UseCategoryTreeResult {
  const [categories, setCategories] = useState<CategoryNode[]>([]);
  const [loadingCategories, setLoadingCategories] = useState(true);
  const [categoryError, setCategoryError] = useState<string | null>(null);
  const [isCategoryOpen, setIsCategoryOpen] = useState(false);
  const [categoryPath, setCategoryPath] = useState<CategoryNode[]>([]);
  const [selectedLeaf, setSelectedLeaf] = useState<CategoryNode | null>(null);

  useEffect(() => {
    const loadCategoryTree = async () => {
      try {
        setLoadingCategories(true);
        const res = await axios.get<CategoryNode[]>("/api/category/tree");
        const serverCategories = res.data ?? [];
        setCategories([...serverCategories]);
        setCategoryError(null);
      } catch (error) {
        console.error("Failed to load category tree", error);
        setCategoryError(
          "Không tải được cây danh mục. Vui lòng thử lại sau.",
        );
      } finally {
        setLoadingCategories(false);
      }
    };
    loadCategoryTree();
  }, []);

  const categoryColumns = useMemo(
    () => buildCategoryColumns(categories, categoryPath),
    [categories, categoryPath],
  );

  const selectedPathLabel =
    selectedLeaf && categoryPath.length > 0
      ? categoryPath.map((n) => n.name).join(" / ")
      : "";

  const handleCategoryClick = useCallback(
    (levelIndex: number, node: CategoryNode) => {
      const nextPath = [...categoryPath.slice(0, levelIndex), node];
      setCategoryPath(nextPath);
      if (!node.children || node.children.length === 0) {
        setSelectedLeaf(node);
      } else {
        setSelectedLeaf(null);
      }
    },
    [categoryPath],
  );

  const openCategoryPopup = useCallback(
    () => setIsCategoryOpen(true),
    [],
  );
  const closeCategoryPopup = useCallback(
    () => setIsCategoryOpen(false),
    [],
  );

  return {
    categories,
    loadingCategories,
    categoryError,
    isCategoryOpen,
    categoryPath,
    selectedLeaf,
    categoryColumns,
    selectedPathLabel,
    handleCategoryClick,
    openCategoryPopup,
    closeCategoryPopup,
  };
}

